import{_ as e,o as l,c as i,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2019-10-07 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-10-07 :: Ceph Orchestration Meeting","date":"2019-10-07T00:00:00.000Z","updated":"2019-10-21T00:00:00.000Z","tags":["Ceph","分布式存储","CI","Jenkins","异步配置","外部集群","Rook","翻译"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-10-07_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-10-07_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-10-07_-_-_Ceph_Orchestration_Meeting.md"};function s(o,t,a,p,_,g){return l(),i("div",null,[...t[0]||(t[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年10月7日</p><p><strong>参会人员</strong>： [请列出参会人员名单]</p><p><strong>会议主题</strong>： 分布式存储Ceph项目讨论</p><p><strong>会议内容</strong>：</p><p><strong>一、Ceph CI更新</strong></p><ul><li>Adam升级了Jenkins版本，并更新了插件，解决了之前CPU使用率过高的问题。</li><li>系统进行了一些磁盘空间清理，将不再保存所有构建，以减少存储压力。</li><li>期待升级后构建更加可靠。</li></ul><p><strong>二、外部集群</strong></p><ul><li>外部集群的PR即将完成，目前处于最终审查阶段。</li><li>即使Arches作为要求可能即将被移除，外部集群功能仍对OCS有益。</li></ul><p><strong>三、Ceph Manager模块异步配置</strong></p><ul><li>讨论了Ceph Manager模块异步配置的PR，主要关注使用互斥锁（mutex）还是通道（channels）。</li><li>决定使用互斥锁，因为它在此场景中更简单。</li><li>建议使用同步组（sync group）来控制并发，以确保在所有模块配置完成后才切换到OSD代码。</li></ul><p><strong>四、卷内信息提取</strong></p><ul><li>讨论了从配置映射中提取卷内信息的PR。</li><li>目前PR已提交，Sebastian开始进行审查。</li><li>目前CI构建出现问题，无法查看构建日志，需要进一步调查。</li></ul><p><strong>五、布宜诺斯艾利斯会议</strong></p><ul><li>Charlotte将在布宜诺斯艾利斯参加一个关于如何为TrueIT项目贡献的演讲。</li><li>演讲将用西班牙语进行。</li></ul><p><strong>六、其他</strong></p><ul><li>会议期间，讨论了一些与编排相关的邮件，但没有紧急事项。</li><li>会议期间，CI构建出现问题，需要进一步调查。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Adam将继续调查CI构建问题。</li><li>Charlotte将继续审查卷内信息提取的PR。</li><li>Sebastian将继续审查外部集群的PR。</li><li>Charlotte将准备布宜诺斯艾利斯的演讲。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到的英文关键词包括：CI、Rook、Cassandra、Jenkins、mutex、channels、sync group、OCS、Arches、TrueIT。</li></ul>',21)])])}const c=e(r,[["render",s]]);export{u as __pageData,c as default};
